import type { StatBlock } from './types.ts'
import { PASSIVE_DATA, type GeneratedEffect } from '../data/passives.generated.ts'

// Relative imports only: the share-link codec (and so the Worker) use this.

/**
 * Combat passives of Dofus, Prysmaradites and legendary items.
 *
 * The numbers come from the game itself: scripts/fetch-passives.ts reads
 * each item's passive spell from the game data and writes every effect on
 * the bearer's stats (value, sign, stack cap) to data/passives.generated.ts,
 * regenerated by the hourly update-data workflow. So a rebalance needs no
 * code change. This file only says how those effects are offered to the
 * player — stacks, mutually exclusive cases, Prysmaradite turns — and an
 * item with no layout here still gets one control per effect.
 */

export type PassiveStat =
  | 'ap' | 'mp' | 'power' | 'damage' | 'critChance' | 'pushbackDamage' | 'dodge' | 'lock'
  | 'apReduction' | 'mpReduction' | 'apParry' | 'mpParry'
  | 'meleeDamagePercent' | 'rangedDamagePercent' | 'spellDamagePercent' | 'finalDamagePercent' | 'targetVulnerabilityPercent'
  | 'strength' | 'intelligence' | 'chance' | 'agility'
  | 'neutralResPercent' | 'earthResPercent' | 'fireResPercent' | 'waterResPercent' | 'airResPercent'

export type PassiveBonus = Partial<Record<PassiveStat, number>>

export type PassiveControl =
  /** 0…max stacks of the same bonus; `shared` caps the stacks of all the item's shared controls together. */
  | { id: string; kind: 'stacks'; max: number; perStack: PassiveBonus; shared?: number }
  /** Off, or one of the options (a single option is a plain toggle; `turn` labels Prysmaradite turns). */
  | { id: string; kind: 'choice'; options: { bonus: PassiveBonus; turn?: number }[] }

const RES_KEYS = ['neutralResPercent', 'earthResPercent', 'fireResPercent', 'waterResPercent', 'airResPercent'] as const
const STATS = new Set<string>([
  'ap', 'mp', 'power', 'damage', 'critChance', 'pushbackDamage', 'dodge', 'lock', 'apReduction', 'mpReduction',
  'apParry', 'mpParry', 'meleeDamagePercent', 'rangedDamagePercent', 'spellDamagePercent', 'finalDamagePercent', 'targetVulnerabilityPercent',
  'strength', 'intelligence', 'chance', 'agility', ...RES_KEYS,
])

/** One generated effect as a bonus ("% Resistance" covers the five elements). */
function effectBonus(e: GeneratedEffect): PassiveBonus {
  if (e.stat === 'resPercentAll') return Object.fromEntries(RES_KEYS.map(k => [k, e.value]))
  return STATS.has(e.stat) ? { [e.stat as PassiveStat]: e.value } : {}
}

function sumBonus(bonuses: PassiveBonus[]): PassiveBonus {
  const out: PassiveBonus = {}
  for (const b of bonuses) for (const [k, v] of Object.entries(b) as [PassiveStat, number][]) out[k] = (out[k] ?? 0) + v
  return out
}

/**
 * Picks a generated effect by stat: 'mp' is the item's first MP effect,
 * 'mp#1' the second (in game data order).
 */
type Pick = string

type Layout =
  /** Stacks of one effect. Cap: the game's, or `cap` when the game sets none
   *  (the player picks the real count, so a generous bound costs nothing). */
  | { stacks: Pick; cap?: number; shared?: true }
  /** Off or one of these cases; each case adds the listed effects. */
  | { options: Pick[][] }
  /** Prysmaradites: the value of turn 1, 2, 3. */
  | { turns: Pick[][] }

// ankama_id → how its effects are offered. Control ids are `${ankamaId}.${i}`
// (saved in builds): only append to a list, never reorder it.
const LAYOUT: Record<number, Layout[]> = {
  // ── Dofus ──
  694:   [{ stacks: 'finalDamagePercent' }],                                    // Crimson: attacked
  739:   [{ stacks: 'finalDamagePercent' }],                                    // Turquoise: critical hits
  958:   [{ options: [['chance'], ['strength'], ['agility'], ['intelligence']] }], // Dofusteuse: one per turn, in rotation
  972:   [{ options: [['apParry'], ['mpParry']] }],                             // Cawwot: AP / MP reduction attempted
  6980:  [{ options: [['finalDamagePercent'], ['lock']] }],                     // Vulbis: not attacked / attacked
  7112:  [{ options: [['damage']] }],                                           // Black-Spotted: dealt damage this turn
  7114:  [{ stacks: 'rangedDamagePercent#1' }, { stacks: 'meleeDamagePercent#1' }], // Ebony
  7754:  [{ options: [['ap'], ['dodge']] }],                                    // Ochre: not attacked / attacked
  8698:  [{ options: [['finalDamagePercent#0'], ['finalDamagePercent#1']] }],   // Cloudy: odd / even turn
  18043: [{ options: [['mp'], ['ap']] }],                                       // Abyssal: no adjacent enemy / adjacent enemy
  20286: [{ options: [['finalDamagePercent']] }],                               // Sparkling Silver: below 20% health
  23237: [{ stacks: 'damage#1', cap: 8 }],                                      // Domakuro: 8 Damage steps, 4 turns × 16 = 64
  26066: [{ options: [['power']] }, { options: [['finalDamagePercent']] }],     // Nightmare: pushback / both effects
  29136: [{ stacks: 'power', cap: 16 }],                                        // Sylvan: per MP used, lasts 2 turns
  31794: [{ stacks: 'finalDamagePercent' }],                                    // Dofzzbz: summon attacked

  // ── Legendary gear ──
  20354: [{ stacks: 'lock', cap: 8 }, { options: [['targetVulnerabilityPercent']] }], // Scissors of Destiny: enemies hit; adjacent enemies suffer more
  20355: [{ stacks: 'ap#1' }],                                                  // Brumaire's Shiver: enemies finished off
  20356: [{ stacks: 'pushbackDamage', cap: 10 }],                               // Buhorado Feather: per critical hit
  20358: [{ options: [['finalDamagePercent']] }],                               // Death-Defying: above 50% health
  20359: [{ stacks: 'finalDamagePercent#1' }],                                  // Bram Worldbeard: AP/MP removals
  20360: [{ options: [['ap#1'], ['ap#0', 'mp']] }],                             // Ganymede: even / odd turn
  20361: [{ stacks: 'rangedDamagePercent#0', cap: 10 }],                        // Rykke Errel: −1% per cell, up to −10%
  20362: RES_KEYS.map(k => ({ stacks: k, shared: true as const })),            // Jahash Jurgen: per element hit, shared cap
  20363: [{ options: [['mp#0'], ['mp#1']] }],                                   // Thousand-League Boots: +2 MP odd turns / −1 MP
  20365: [{ options: [['mp', 'critChance'], ['dodge', 'pushbackDamage']] }],   // Dodge's Audacity: moved / not moved
  20366: [{ stacks: 'spellDamagePercent#1' }],                                  // Lady Jhessica's Courage: enemies hit
  22368: [{ stacks: 'mp#1' }],                                                  // War's Halbaxe: enemies finished off
  22444: [{ stacks: 'resPercentAll' }],                                         // Misery's Flail-Scale: reductions attempted
  32114: [{ stacks: 'finalDamagePercent' }],                                    // Oto Mustam: enemies alive
  32116: [{ stacks: 'pushbackDamage', cap: 16 }],                               // Menalt: per MP used, lasts 2 turns
  32117: [{ stacks: 'finalDamagePercent', cap: 4 }, { options: [['targetVulnerabilityPercent']] }], // Thanatena: per kill; everyone suffers more
  32119: [{ options: [['ap']] }],                                               // Henual: teleported / switched places
  32121: [{ stacks: 'mpReduction', shared: true }, { stacks: 'apReduction', shared: true }], // Meriana: Earth/Water, Fire/Air hits
  32163: [{ stacks: 'resPercentAll' }],                                         // Amayiro: enemies alive

  // ── Prysmaradites ──
  21996: [{ options: [['finalDamagePercent', 'ap']] }],                         // Pryssure-O-Mat
  21997: [{ options: [['finalDamagePercent', 'ap']] }],                         // Shiny Pryssure
  21998: [{ options: [['finalDamagePercent', 'ap']] }],                         // Iridescent Pryssure
  22001: [{ turns: [['critChance#0'], ['critChance#1'], ['critChance#2']] }],   // Surpryz
  22004: [{ turns: [['finalDamagePercent#0', 'resPercentAll#0'], ['finalDamagePercent#1', 'resPercentAll#1'], ['finalDamagePercent#2', 'resPercentAll#2']] }], // Prynyang
  22007: [{ stacks: 'mp' }],                                                    // Prycapture: enemies more than 9 cells away
  22011: [{ turns: [['ap']] }],                                                 // Prysipitate-O-Mat
  22012: [{ turns: [['mp', 'ap']] }],                                           // Shiny Prysipitate
  22013: [{ turns: [['mp', 'ap']] }],                                           // Iridescent Prysipitate
  22014: [{ turns: [['apReduction#0', 'mpReduction#0'], ['apReduction#1', 'mpReduction#1'], ['apReduction#2', 'mpReduction#2']] }], // Spryritual
  22015: [{ turns: [['apParry#0', 'mpParry#0'], ['apParry#1', 'mpParry#1'], ['apParry#2', 'mpParry#2']] }], // Prysical
  22023: [{ stacks: 'meleeDamagePercent', cap: 16 }],                           // Pryximity: enemies within 3 cells, start + end of turn
}

/** Without a game stack cap or a `cap` in the layout, stacks stop here. */
const DEFAULT_CAP = 10

/** Resolves a pick against an item's generated effects; undefined when the game data changed shape. */
export function pickEffect(effects: GeneratedEffect[], pick: Pick): GeneratedEffect | undefined {
  const [stat, n] = pick.split('#')
  return effects.filter(e => e.stat === stat)[Number(n ?? 0)]
}

function fromLayout(ankamaId: number, effects: GeneratedEffect[], layout: Layout[]): PassiveControl[] | null {
  const controls: PassiveControl[] = []
  for (const [i, entry] of layout.entries()) {
    const id = `${ankamaId}.${i}`
    if ('stacks' in entry) {
      const e = pickEffect(effects, entry.stacks)
      if (!e) return null
      const max = e.maxStack ?? entry.cap ?? DEFAULT_CAP
      controls.push({ id, kind: 'stacks', max, perStack: effectBonus(e), ...(entry.shared ? { shared: max } : {}) })
      continue
    }
    const cases = 'turns' in entry ? entry.turns : entry.options
    const options: { bonus: PassiveBonus; turn?: number }[] = []
    for (const [t, picks] of cases.entries()) {
      const picked = picks.map(p => pickEffect(effects, p))
      if (picked.some(p => !p)) return null
      options.push({ bonus: sumBonus(picked.map(p => effectBonus(p!))), ...('turns' in entry ? { turn: t + 1 } : {}) })
    }
    controls.push({ id, kind: 'choice', options })
  }
  return controls
}

/** An item without a layout (or whose game data changed shape): one control per effect. */
function fallback(ankamaId: number, effects: GeneratedEffect[]): PassiveControl[] {
  return effects.filter(e => Object.keys(effectBonus(e)).length > 0).map((e, i) => {
    const id = `${ankamaId}.auto${i}`
    return e.maxStack && e.maxStack > 1
      ? { id, kind: 'stacks' as const, max: e.maxStack, perStack: effectBonus(e) }
      : { id, kind: 'choice' as const, options: [{ bonus: effectBonus(e) }] }
  })
}

/** Items laid out by hand whose game data no longer fits the layout (shown with the fallback). */
export const LAYOUT_MISMATCHES: number[] = []

export const ITEM_PASSIVES: ReadonlyMap<number, PassiveControl[]> = new Map(
  Object.entries(PASSIVE_DATA).flatMap(([key, data]) => {
    const ankamaId = Number(key)
    if (data.effects.length === 0) return []
    const layout = LAYOUT[ankamaId]
    let controls = layout ? fromLayout(ankamaId, data.effects, layout) : null
    if (layout && !controls) LAYOUT_MISMATCHES.push(ankamaId)
    controls ??= fallback(ankamaId, data.effects)
    return controls.length > 0 ? [[ankamaId, controls] as const] : []
  }),
)

/** Ids with a hand layout (tests check every passive item with stats has one). */
export const LAID_OUT_ITEMS: ReadonlySet<number> = new Set(Object.keys(LAYOUT).map(Number))

/**
 * Real passives with no effect on the bearer's stats (shields, heals,
 * states, effects on other fighters): shown as their item text only.
 */
export const TEXT_ONLY_PASSIVES: ReadonlySet<number> = new Set(
  Object.keys(PASSIVE_DATA).map(Number).filter(id => !ITEM_PASSIVES.has(id)),
)

/** Item has a combat passive (with or without stats to model). */
export const hasPassive = (ankamaId: number) => ankamaId in PASSIVE_DATA

const CONTROL_BY_ID = new Map([...ITEM_PASSIVES.values()].flat().map(c => [c.id, c]))

/** Highest value a control takes: its stacks, or its number of options. */
export const controlMax = (c: PassiveControl) => (c.kind === 'stacks' ? c.max : c.options.length)

/** Player's passive settings: control id → stacks, or option number (0 = off). */
export type PassiveState = Record<string, number>

const itemOf = (controlId: string) => Number(controlId.split('.')[0])

/**
 * Stacks this control may still take: its own max, and for shared stacks
 * ("stackable 5 times, shared between elements") what the item's other
 * shared controls leave.
 */
export function controlRoom(control: PassiveControl, state: PassiveState): number {
  if (control.kind !== 'stacks' || !control.shared) return controlMax(control)
  const others = (ITEM_PASSIVES.get(itemOf(control.id)) ?? [])
    .filter(c => c.id !== control.id && c.kind === 'stacks' && c.shared)
    .reduce((sum, c) => sum + (state[c.id] ?? 0), 0)
  return Math.max(0, Math.min(control.max, control.shared - others))
}

/**
 * Keeps known controls with in-range integer values (untrusted input:
 * links, DB rows); shared stacks are trimmed in control order.
 */
export function sanitizePassiveState(raw: unknown): PassiveState {
  if (raw == null || typeof raw !== 'object' || Array.isArray(raw)) return {}
  const clamped = new Map<string, number>()
  for (const [id, v] of Object.entries(raw as Record<string, unknown>)) {
    const control = CONTROL_BY_ID.get(id)
    if (!control || typeof v !== 'number' || !Number.isFinite(v)) continue
    clamped.set(id, Math.min(controlMax(control), Math.max(0, Math.trunc(v))))
  }
  const out: PassiveState = {}
  for (const control of CONTROL_BY_ID.values()) {
    const v = clamped.get(control.id)
    if (!v) continue
    const n = Math.min(v, controlRoom(control, out))
    if (n > 0) out[control.id] = n
  }
  return out
}

/** Sets one control, keeping it within its room (shared stacks never exceed their cap). */
export function setControl(state: PassiveState, id: string, value: number): PassiveState {
  const control = CONTROL_BY_ID.get(id)
  if (!control) return sanitizePassiveState(state)
  const { [id]: _previous, ...rest } = state
  return sanitizePassiveState({ ...rest, [id]: Math.min(value, controlRoom(control, rest)) })
}

function addBonus(into: PassiveBonus, bonus: PassiveBonus, times = 1) {
  for (const [k, v] of Object.entries(bonus) as [PassiveStat, number][]) {
    into[k] = (into[k] ?? 0) + v * times
  }
}

/** Value one control adds at the given setting. */
export function controlBonus(control: PassiveControl, value: number): PassiveBonus {
  const out: PassiveBonus = {}
  if (value <= 0) return out
  if (control.kind === 'stacks') addBonus(out, control.perStack, Math.min(value, control.max))
  else if (control.options[value - 1]) addBonus(out, control.options[value - 1].bonus)
  return out
}

/** Total bonus of the passives of the equipped items (unequipped items count nothing). */
export function passiveBonus(equippedIds: Iterable<number | null | undefined>, rawState: PassiveState): PassiveBonus {
  const state = sanitizePassiveState(rawState)
  const out: PassiveBonus = {}
  const seen = new Set<number>()
  for (const id of equippedIds) {
    if (id == null || seen.has(id)) continue
    seen.add(id)
    for (const control of ITEM_PASSIVES.get(id) ?? []) addBonus(out, controlBonus(control, state[control.id] ?? 0))
  }
  for (const k of Object.keys(out) as PassiveStat[]) if (out[k] === 0) delete out[k]
  return out
}

const ELEMENT_DAMAGE = ['neutralDamage', 'earthDamage', 'fireDamage', 'waterDamage', 'airDamage'] as const
const RES_CAP = 50

/**
 * Gear stats plus a passive bonus: the in-combat stats used for damage and
 * the PvP arena. Generic Damage also goes into every element (as in
 * computeStats); % resistances keep the 50% cap. AP/MP/Range are combat
 * buffs, so the gear caps do not apply to them.
 */
export function withPassives(stats: StatBlock, bonus: PassiveBonus): StatBlock {
  if (Object.keys(bonus).length === 0) return stats
  const next: StatBlock = { ...stats }
  const rec = next as unknown as Record<string, number>
  for (const [k, v] of Object.entries(bonus) as [PassiveStat, number][]) rec[k] = (rec[k] ?? 0) + v
  if (bonus.damage) for (const k of ELEMENT_DAMAGE) next[k] += bonus.damage
  for (const k of RES_KEYS) {
    if (bonus[k]) {
      const raw = `${k}Raw` as keyof StatBlock
      ;(next as unknown as Record<string, number>)[raw] = (stats[raw] as number) + bonus[k]!
      next[k] = Math.min(RES_CAP, (stats[raw] as number) + bonus[k]!)
    }
  }
  return next
}
